import{_ as a,o,c as t,a7 as r}from"./chunks/framework.FWlv_suP.js";const f=JSON.parse('{"title":"Radio Bee Data Collection","description":"Official Data Collection for Radio Bee.","frontmatter":{"title":"Radio Bee Data Collection","description":"Official Data Collection for Radio Bee.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/radio-bee.md","filePath":"data-collection/radio-bee.md"}'),i={name:"data-collection/radio-bee.md"};function n(s,e,l,d,c,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="radio-bee-data-collection" tabindex="-1">Radio Bee Data Collection <a class="header-anchor" href="#radio-bee-data-collection" aria-label="Permalink to &quot;Radio Bee Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> November 22, 2026</p><h2 id="local-app-data" tabindex="-1">Local app data <a class="header-anchor" href="#local-app-data" aria-label="Permalink to &quot;Local app data&quot;">​</a></h2><p>Radio Bee stores favorites, language and display preferences, home station selections, filter settings, and station catalogue cache on your device. This local data is not sent to a developer-operated user account.</p><h2 id="network-requests" tabindex="-1">Network requests <a class="header-anchor" href="#network-requests" aria-label="Permalink to &quot;Network requests&quot;">​</a></h2><p>The app retrieves station directories and streams through third-party providers. Those services receive ordinary technical information required for network requests, potentially including IP address, device or browser details, and requested resources. Their own practices apply.</p><h2 id="contact-form-data" tabindex="-1">Contact form data <a class="header-anchor" href="#contact-form-data" aria-label="Permalink to &quot;Contact form data&quot;">​</a></h2><p>Using the optional Google Forms contact form sends your name, email, inquiry purpose, and any optional details you enter (such as phone number, message, or station information) to Google Forms and the Radio Bee operator for support or related inquiries. Form submissions are voluntary and require in-app consent.</p><h2 id="permissions-and-services" tabindex="-1">Permissions and services <a class="header-anchor" href="#permissions-and-services" aria-label="Permalink to &quot;Permissions and services&quot;">​</a></h2><p>Internet connectivity is needed to load catalogues and play radio. The reviewed public listening features do not require location, camera, microphone, contacts, phone, SMS, or broad storage permissions. There is no developer-operated account, advertising SDK, or analytics service in the reviewed app.</p><h2 id="google-play-data-safety" tabindex="-1">Google Play Data safety <a class="header-anchor" href="#google-play-data-safety" aria-label="Permalink to &quot;Google Play Data safety&quot;">​</a></h2><p>The Play Console declaration must reflect the actual Android App Bundle, integrated services, network transmissions, and optional contact-form submissions. Do not mark the entire app as having no data collection without checking the contact form and third-party processing.</p><p>Questions: <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',13)])])}const u=a(i,[["render",n]]);export{f as __pageData,u as default};
